(EXISTS (SELECT 1 FROM unnest(array[
   'public.settle_typed_inventory_page(text,text,uuid,uuid,uuid,text,text,text,jsonb,timestamp with time zone)',
   'public.fail_typed_inventory_scan(text,text,uuid,uuid,uuid,text,text,text,timestamp with time zone)',
   'public.defer_typed_inventory_claims_after_daily_quota(uuid,jsonb,timestamp with time zone)'
 ]::text[]) AS expected(v_signature) WHERE ( not EXISTS(SELECT 1 from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)) or not (SELECT prosecdef from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)) or pg_catalog.pg_get_userbyid((SELECT proowner from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)))<>'postgres'
     or (SELECT proacl from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)) is distinct from '{postgres=X/postgres,service_role=X/postgres}'::aclitem[]
     or (SELECT proconfig from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)) is distinct from (case when (SELECT proname from pg_catalog.pg_proc where oid=to_regprocedure(expected.v_signature)) in ('settle_typed_inventory_page','fail_typed_inventory_scan')
     then array['search_path=pg_catalog, public, extensions, pg_temp']
     else array['search_path=pg_catalog, public, pg_temp'] end)
   ) IS TRUE)) IS TRUE

(EXISTS (SELECT 1 FROM requirements_2 AS cols WHERE ( NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid=to_regclass('public.'||cols.table_name)
    AND a.attname=cols.column_name AND NOT a.attisdropped AND a.atttypid=to_regtype(cols.type_name) AND a.attnotnull=cols.not_null)
  ) IS TRUE)) IS TRUE

(EXISTS (SELECT 1 FROM requirements_3 AS checks WHERE ( NOT EXISTS(SELECT 1 FROM pg_catalog.pg_constraint c WHERE c.conrelid=to_regclass('public.'||checks.table_name)
    AND c.conname=checks.constraint_name AND c.contype::text=checks.kind AND c.convalidated)
  ) IS TRUE)) IS TRUE

(EXISTS (SELECT 1 FROM unnest(array[
        'public.inspect_typed_inventory_canonical_repair(integer)',
        'public.repair_typed_inventory_canonical_types(integer,text)',
        'public.assert_typed_inventory_canonical_repair_schema()'
    ]::text[]) AS expected(v_signature) WHERE ( not pg_catalog.has_function_privilege(
            'service_role', to_regprocedure(expected.v_signature), 'execute'
        )
           or pg_catalog.has_function_privilege(
               'anon', to_regprocedure(expected.v_signature), 'execute'
           )
           or pg_catalog.has_function_privilege(
               'authenticated', to_regprocedure(expected.v_signature), 'execute'
           )
        ) IS TRUE)) IS TRUE

